const body = $('Entrada').first().json.body || {};
const ctx = body.context && typeof body.context === 'object' ? body.context : {};
const filas = $input.all().map((i) => i.json).filter((r) => r && r.record_key);

// Se replica la forma que arma 08b en el chatbot: renderCatalog exige
// catalog_ready y los paquetes indexados por SKU, no una lista suelta.
const paquetes = {};
for (const r of filas) {
  if (String(r.category) !== 'package') continue;
  paquetes[String(r.sku)] = {
    sku: r.sku, name: r.name,
    price_project: Number(r.price_project || 0),
    price_monthly: Number(r.price_monthly || 0),
    includes_text: r.includes_text || '',
  };
}
const catalogo = {
  catalog_ready: Object.keys(paquetes).length > 0,
  catalog_source: 'banco',
  catalog_version: filas[0]?.version || 'test',
  catalog_packages: paquetes,
  catalog_price_map: {},
  catalog_domains: filas.filter(r=>String(r.category)==='domain'),
  catalog_addons: filas.filter(r=>String(r.category)==='addon'),
  catalog_rules: filas.filter(r=>String(r.category)==='rule'),
};
return [{ json: {
  user_message: String(body.user_message || ''),
  message_type: 'text',
  context_json: JSON.stringify({ schema_version: '3.0', conversation_id: 'test-1', ...ctx }),
  catalog_json: JSON.stringify(catalogo),
  source_hash: 'banco-de-pruebas',
  environment: 'staging',
}}];

const r = $input.first().json || {};
const campos = ['business_type','project_goal','pain_point','current_process','impact','desired_outcome','discovery_urgency','discovery_depth','discovery_done','last_question_code','recommended_solution','selected_solution','solution_confirmed','price_requested','proposal_requested','pipeline_stage','lead_status','first_name','name','email','objection_code','handoff_reason'];
const estado = {};
for (const c of campos) if (r[c] !== undefined && r[c] !== '') estado[c] = r[c];
return [{ json: {
  reply: String(r.final_reply || r.reply || ''),
  intent: r.interpretation?.intent || '',
  next_question_code: r.next_question_code || '',
  action: r.action_request?.type || 'none',
  reason_code: r.reason_code || '',
  estado,
}}];
